const p=$input.first().json;
const raw=p.raw_data||p;
const context={
  event_id:p._constellation_event_id||p._event_id||`AI-${Date.now()}`,
  event_type:raw.event_type||raw.type||'security_alert',
  severity:raw.severity||'Medium',
  rule_desc:raw.rule_desc||raw.message||'Unknown rule',
  src_ip:raw.src_ip||raw.source_ip||null,
  username:raw.username||raw.user||null,
  asset:raw.agent_name||raw.asset_id||raw.hostname||null,
  asset_criticality:raw.asset_data&&raw.asset_data.criticality||raw.asset_criticality||'unknown',
  geo:raw.geo_data||null,
  vt_score:raw.vt_score||null,
  confidence_score:raw.confidence_score||p.confidence_score||50,
  risk_level:raw.risk_level||'Medium'
};
return[{json:{...p,_ai_context:context}}];

