const claudeResp=$input.first().json;
const originalEvent=$('Build AI Context').first().json;
const rawText=claudeResp.content&&claudeResp.content[0]&&claudeResp.content[0].text||'{}';
let analysis={};
try{
  const clean=rawText.replace(/```json|```/g,'').trim();
  analysis=JSON.parse(clean);
}catch(e){
  analysis={
    threat_narrative:'AI parse error: '+rawText.substring(0,100),
    kill_chain_stage:'Unknown',
    mitre_techniques:[],
    immediate_actions:['Manual review required — AI parsing failed'],
    urgency:'Normal',
    analyst_verdict_hint:'needs_investigation',
    confidence_in_analysis:0,
    _parse_error:e.message
  };
}
return[{json:{
  ...originalEvent,
  ai_enrichment:{
    ...analysis,
    enriched_at:new Date().toISOString(),
    model_used:'claude-opus-4-5',
    tokens_used:(claudeResp.usage&&(claudeResp.usage.input_tokens+claudeResp.usage.output_tokens))||0
  },
  kill_chain_stage:analysis.kill_chain_stage,
  urgency:analysis.urgency,
  analyst_verdict_hint:analysis.analyst_verdict_hint,
  threat_narrative:analysis.threat_narrative
}}];
